const stars: Star[] = ROWS.map(([ra, dec, magnitude, name]) => ({ ra, dec, magnitude, name }));

const MARGIN = 10;
// The hour labels sit 4 degrees below the celestial equator, so the sphere has to
// stop short of the frame to leave them room.
const RIM = 1.1;

const outline = d3.geoCircle().radius(90).center([0, 90])();
const graticule = d3
  .geoGraticule()
  .stepMinor([15, 10])
  .extent([
    [-180, 0],
    [180, 90]
  ])();

const formatMagnitude = d3.format('.2f');

/** One star per row: right ascension in degrees, declination, and apparent magnitude. */
export type Data = { ra: number; dec: number; magnitude: number; name?: string }[];

export default function StarMap({ data = stars, width }: { data?: Data; width: number }) {
  const height = width;
  const [hovered, setHovered] = useState<number | null>(null);

  const sky = useMemo(() => {
    const cx = width / 2;
    const cy = width / 2;
    const radius = Math.max((width - 2 * MARGIN) / 2 / RIM, 0);
    const projection = d3
      .geoStereographic()
      .reflectY(true) // the sky is seen from inside, so east runs counterclockwise
      .rotate([0, -90]) // north celestial pole at the centre
      .translate([cx, cy])
      .scale(radius)
      .precision(0.1);
    const path = d3.geoPath(projection);
    const at = (lon: number, lat: number): [number, number] => projection([lon, lat]) ?? [cx, cy];

    // Right ascension runs 0h to 24h over 360 degrees, so one hour is 15 degrees.
    const minuteTicks = d3.range(0, 1440, 5).map((m) => {
      const [x1, y1] = at(m / 4, 0);
      const [x2, y2] = at(m / 4, m % 60 ? -1 : -2);
      return { key: m, x1, y1, x2, y2 };
    });

    const hourLabels = d3.range(0, 24).map((h) => {
      const [x, y] = at(h * 15, -4);
      return { key: h, x, y, label: `${h}h`, major: h === 0 };
    });

    const decLabels = d3.range(10, 90, 10).map((d) => {
      const [x, y] = at(0, d);
      return { key: d, x, y, label: `${d}°` };
    });

    const points = data.map((s) => at(s.ra, s.dec));
    const voronoi = d3.Delaunay.from(points).voronoi([0, 0, width, height]);

    return {
      cx,
      cy,
      radius,
      graticule: path(graticule) ?? undefined,
      outline: path(outline) ?? undefined,
      minuteTicks,
      hourLabels,
      decLabels,
      points,
      // Voronoi cells make every star, however small, an easy hover target.
      cells: data.map((_, i) => voronoi.renderCell(i)),
      // Brighter stars carry a LOWER magnitude, so the radius scale runs backwards.
      starRadius: d3.scaleLinear([6, -1], [0, (8 * width) / 954])
    };
  }, [data, width, height]);

  if (width === 0) return null;

  const focus = hovered === null ? null : sky.points[hovered];
  const focusDistance = focus ? Math.hypot(focus[0] - sky.cx, focus[1] - sky.cy) : 0;
  const focusAngle = focus ? Math.atan2(focus[1] - sky.cy, focus[0] - sky.cx) : 0;
  const reach = sky.radius * RIM;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Star map of the northern celestial hemisphere on a stereographic projection, with the 600 brightest stars sized by apparent magnitude"
    >
      <defs>
        <radialGradient id="star-map-sky">
          <stop offset="0%" stopColor="#0b2350" />
          <stop offset="100%" stopColor="#061616" />
        </radialGradient>
      </defs>

      <circle cx={sky.cx} cy={sky.cy} r={sky.radius} fill="url(#star-map-sky)" />
      <path d={sky.graticule} fill="none" stroke="var(--text)" strokeOpacity={0.18} />
      <path d={sky.outline} fill="none" stroke="var(--text)" strokeOpacity={0.6} />

      <g stroke="var(--text)" strokeOpacity={0.6}>
        {sky.minuteTicks.map((t) => (
          <line key={t.key} x1={t.x1} y1={t.y1} x2={t.x2} y2={t.y2} />
        ))}
      </g>

      <g fill="var(--muted)" textAnchor="middle" fontSize={10}>
        {sky.hourLabels.map((t) => (
          <text
            key={t.key}
            x={t.x}
            y={t.y}
            dy="0.35em"
            fontSize={t.major ? 13 : undefined}
            fontWeight={t.major ? 600 : undefined}
          >
            {t.label}
          </text>
        ))}
        {sky.decLabels.map((t) => (
          <text key={t.key} x={t.x} y={t.y} dy="0.35em">
            {t.label}
          </text>
        ))}
      </g>

      {focus && (
        <g stroke="var(--accent)" fill="none" strokeOpacity={0.8}>
          <circle cx={sky.cx} cy={sky.cy} r={focusDistance} />
          <line
            x1={sky.cx}
            y1={sky.cy}
            x2={sky.cx + reach * Math.cos(focusAngle)}
            y2={sky.cy + reach * Math.sin(focusAngle)}
          />
        </g>
      )}

      <g fill="var(--text)">
        {data.map((s, i) => (
          <circle
            key={i}
            cx={sky.points[i][0]}
            cy={sky.points[i][1]}
            r={sky.starRadius(s.magnitude)}
          />
        ))}
      </g>

      <g fill="none" pointerEvents="all">
        {sky.cells.map((cell, i) => (
          <path
            key={i}
            d={cell}
            onMouseEnter={() => setHovered(i)}
            onMouseLeave={() => setHovered(null)}
          />
        ))}
      </g>

      {hovered !== null && (
        <text x={MARGIN} y={MARGIN + 12} fill="var(--accent)" fontSize={12}>
          {data[hovered].name ?? 'unnamed'} · magnitude{' '}
          {formatMagnitude(data[hovered].magnitude)}
        </text>
      )}
    </svg>
  );
}
